17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.util.UriComponentsBuilder;
44	
45	import jakarta.transaction.Transactional;
46	
47	/**
48	 * @author Vitaliy Fedoriv
49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        HttpHeaders headers = new HttpHeaders();
105	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
106	        this.clinicService.saveOwner(owner);
107	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
108	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
109	            ownerMapper.membershipLevel(owner));
110	        AUDIT.info(OwnerCreatedEvent.next(owner.getId(), owner.getMemberId(), ownerMapper.membershipLevel(owner)).toJson());
111	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
112	        headers.setLocation(UriComponentsBuilder.newInstance()
113	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
114	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
120	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
121	        if (currentOwner == null) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        currentOwner.setAddress(ownerFieldsDto.getAddress());
125	        currentOwner.setCity(ownerFieldsDto.getCity());
126	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
127	        currentOwner.setLastName(ownerFieldsDto.getLastName());
128	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
129	        this.clinicService.saveOwner(currentOwner);
130	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Transactional
135	    @Override
136	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
137	        Owner owner = this.clinicService.findOwnerById(ownerId);
138	        if (owner == null) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        owner.setDeleted(true);
142	        this.clinicService.saveOwner(owner);
143	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
149	        Owner owner = this.clinicService.findOwnerById(ownerId);
150	        if (owner == null) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        HttpHeaders headers = new HttpHeaders();
154	        Pet pet = petMapper.toPet(petFieldsDto);
155	        owner.setId(ownerId);
156	        pet.setOwner(owner);
157	        pet.getType().setName(null);
158	        this.clinicService.savePet(pet);
159	        PetDto petDto = petMapper.toPetDto(pet);
160	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
161	            .buildAndExpand(pet.getId()).toUri());
162	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
168	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
169	        if (currentOwner != null) {
170	            Pet currentPet = this.clinicService.findPetById(petId);
171	            if (currentPet != null) {
172	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
173	                currentPet.setName(petFieldsDto.getName());
174	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
175	                this.clinicService.savePet(currentPet);
176	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
177	            }
178	        }
179	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	    }
181	
182	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
183	    @Override
184	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
185	        HttpHeaders headers = new HttpHeaders();
186	        Visit visit = visitMapper.toVisit(visitFieldsDto);
187	        Pet pet = new Pet();
188	        pet.setId(petId);
189	        visit.setPet(pet);
190	        this.clinicService.saveVisit(visit);
191	        VisitDto visitDto = visitMapper.toVisitDto(visit);
192	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
193	            .buildAndExpand(visit.getId()).toUri());
194	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
195	    }
196	
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Override
200	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
201	        Owner owner = this.clinicService.findOwnerById(ownerId);
202	        if (owner != null) {
203	            Pet pet = owner.getPet(petId);
204	            if (pet != null) {
205	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
206	            }
207	        }
208	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
209	    }
210	}
