26	
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be valid E.164")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    private String email;
55	
56	    @Column(name = "postcode")
57	    private String postcode;
58	
59	    @Column(name = "registration_date", columnDefinition = "DATE")
60	    private java.time.LocalDate registrationDate;
61	
62	    @Column(name = "birth_date", columnDefinition = "DATE")
63	    private java.time.LocalDate birthDate;
64	
65	    public java.time.LocalDate getBirthDate() {
66	        return this.birthDate;
67	    }
68	
69	    public void setBirthDate(java.time.LocalDate birthDate) {
70	        this.birthDate = birthDate;
71	    }
72	
73	    @Column(name = "customer_code")
74	    private String memberId;
75	
76	    @Column(name = "household_id")
77	    private String householdId;
78	
79	    @Column(name = "namesake_count")
80	    private Integer namesakeCount;
81	
82	    @Column(name = "household_member_count")
83	    private Integer householdMemberCount;
84	
85	    @Column(name = "membership_level")
86	    private Integer membershipLevel;
87	
88	    public Integer getMembershipLevel() {
89	        return this.membershipLevel;
90	    }
91	
92	    @Column(name = "possible_duplicate_of")
93	    private Integer possibleDuplicateOf;
94	
95	    @Column(name = "deleted")
96	    private boolean deleted;
97	
98	    public boolean isDeleted() {
99	        return this.deleted;
100	    }
101	
102	    public void setDeleted(boolean deleted) {
103	        this.deleted = deleted;
104	    }
105	
106	    public Integer getPossibleDuplicateOf() {
107	        return this.possibleDuplicateOf;
108	    }
109	
110	    /** Record the id of an existing owner this one is a possible (soft) duplicate of, or null. */
111	    public void assignPossibleDuplicate(Collection<Owner> existingOwners) {
112	        this.possibleDuplicateOf = org.springframework.samples.petclinic.util.PossibleDuplicates.matchIn(this, existingOwners);
113	    }
114	
115	    public String getMemberId() {
116	        return this.memberId;
117	    }
118	
119	    public Integer getNamesakeCount() {
120	        return this.namesakeCount;
121	    }
122	
123	    public void setNamesakeCount(Integer namesakeCount) {
124	        this.namesakeCount = namesakeCount;
125	    }
126	
127	    /** Record how many of {@code existingOwners} share this owner's first and last name, case-insensitively. */
128	    public void assignNamesakeCount(Collection<Owner> existingOwners) {
129	        int count = 0;
130	        for (Owner other : existingOwners) {
131	            if (getFirstName().equalsIgnoreCase(other.getFirstName())
132	                && getLastName().equalsIgnoreCase(other.getLastName())) {
133	                count++;
134	            }
135	        }
136	        this.namesakeCount = count;
137	        assignHouseholdMemberCount(existingOwners);
138	        this.membershipLevel = org.springframework.samples.petclinic.util.MembershipLevels.cap(this, existingOwners);
139	    }
140	
141	    public Integer getHouseholdMemberCount() {
142	        return this.householdMemberCount;
143	    }
144	
145	    /** Record how many owners (this one included) share this owner's household after this create. */
146	    public void assignHouseholdMemberCount(Collection<Owner> existingOwners) {
147	        int count = 1;
148	        for (Owner other : existingOwners) {
149	            if (householdId != null && householdId.equals(other.getHouseholdId())) {
150	                count++;
151	            }
152	        }
153	        this.householdMemberCount = count;
154	    }
155	
156	    public String getHouseholdId() {
157	        return this.householdId;
158	    }
159	
160	    public void setHouseholdId(String householdId) {
161	        this.householdId = householdId;
162	    }
163	
164	    /** Assign the '<REGION><FY><HASH8><CHK>' member id: region from the postcode, HASH8 from telephone+lastName, FY from the registration date. */
165	    public void assignMemberId(Collection<Owner> existingOwners) {
166	        this.memberId = MemberIds.buildUnique(getCity(), getPostcode(), getTelephone(), getLastName(), getRegistrationDate(), existingOwners);
167	    }
168	
169	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
170	    private Set<Pet> pets;
171	
172	    public java.time.LocalDate getRegistrationDate() {
173	        return this.registrationDate;
174	    }
175	
176	    public void setRegistrationDate(java.time.LocalDate registrationDate) {
177	        this.registrationDate = registrationDate;
178	    }
179	
180	    @Transient
181	    private String addressLine1;
182	
183	    public String getAddressLine1() {
184	        return this.addressLine1;
185	    }
186	
187	    /** Store addressLine1 normalized so it is returned in canonical form. */
188	    public void setAddressLine1(String addressLine1) {
189	        this.addressLine1 = AddressNormalizer.normalize(addressLine1);
190	    }
191	
192	    public String getAddress() {
193	        return this.address;
194	    }
195	
196	    /** Store the address normalized so create persists and returns the canonical form. */
197	    public void setAddress(String address) {
198	        this.address = AddressNormalizer.normalize(address);
199	    }
200	
201	    public String getCity() {
202	        return this.city;
203	    }
204	
205	    public void setCity(String city) {
206	        this.city = city;
207	    }
208	
209	    public String getTelephone() {
210	        return this.telephone;
211	    }
212	
213	    /** Store the telephone in E.164 form so create and update persist and return it normalized. */
214	    public void setTelephone(String telephone) {
215	        this.telephone = TelephoneNormalizer.toE164(telephone);
216	    }
217	
218	    public String getPostcode() {
219	        return this.postcode;
220	    }
221	
222	    public void setPostcode(String postcode) {
223	        this.postcode = postcode;
224	    }
225	
226	    public String getEmail() {
227	        return this.email;
228	    }
229	
230	    /** Store the address lower-cased so it is persisted and returned normalized. */
231	    public void setEmail(String email) {
232	        this.email = (email == null) ? null : email.toLowerCase(Locale.ROOT);
233	    }
234	
235	    protected Set<Pet> getPetsInternal() {
236	        if (this.pets == null) {
237	            this.pets = new HashSet<>();
238	        }
239	        return this.pets;
240	    }
241	
242	    protected void setPetsInternal(Set<Pet> pets) {
243	        this.pets = pets;
244	    }
245	
246	    public List<Pet> getPets() {
247	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
248	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
249	        return Collections.unmodifiableList(sortedPets);
250	    }
251	
252	    public void setPets(List<Pet> pets) {
253	        this.pets = new HashSet<>(pets);
254	    }
255	
256	    public void addPet(Pet pet) {
257	        getPetsInternal().add(pet);
258	        pet.setOwner(this);
259	    }
260	
261	    /**
262	     * Return the Pet with the given name, or null if none found for this Owner.
263	     *
264	     * @param name to test
265	     * @return true if pet name is already in use
266	     */
267	    public Pet getPet(String name) {
268	        return getPet(name, false);
269	    }
270	
271	    /**
272	     * Return the Pet with the given name, or null if none found for this Owner.
273	     *
274	     * @param name to test
275	     * @return true if pet name is already in use
276	     */
277	    public Pet getPet(String name, boolean ignoreNew) {
278	        name = name.toLowerCase();
279	        for (Pet pet : getPetsInternal()) {
280	            if (!ignoreNew || !pet.isNew()) {
281	                String compName = pet.getName();
282	                compName = compName.toLowerCase();
283	                if (compName.equals(name)) {
284	                    return pet;
285	                }
286	            }
287	        }
288	        return null;
289	    }
290	
291	    public Pet getPet(Integer petId) {
292	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
293	    }
294	
295	    @Override
296	    public String toString() {
297	        return new ToStringCreator(this)
298	
299	            .append("id", this.getId())
300	            .append("new", this.isNew())
301	            .append("lastName", this.getLastName())
302	            .append("firstName", this.getFirstName())
303	            .append("address", this.address)
304	            .append("city", this.city)
305	            .append("telephone", this.telephone)
306	            .toString();
307	    }
308	}
