37	/**
38	 * Rejects a create/update owner request whose required text fields (firstName, lastName,
39	 * address, city, telephone) are missing or blank, responding 400 with a JSON body whose
40	 * {@code errors} array names each offending field. The check runs before Bean Validation
41	 * so blank (whitespace-only) values are caught in addition to absent ones.
42	 */
43	@ControllerAdvice
44	@Order(Ordered.HIGHEST_PRECEDENCE)
45	public class OwnerRequiredFieldsAdvice implements RequestBodyAdvice {
46	
47	    @Override
48	    public boolean supports(MethodParameter methodParameter, Type targetType,
49	                            Class<? extends HttpMessageConverter<?>> converterType) {
50	        return OwnerFieldsDto.class.equals(targetType);
51	    }
52	
53	    @Override
54	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
55	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
56	        OwnerFieldsDto owner = (OwnerFieldsDto) body;
57	        List<String> missing = new ArrayList<>();
58	        addIfBlank(missing, "firstName", owner.getFirstName());
59	        addIfBlank(missing, "lastName", owner.getLastName());
60	        if (isBlank(owner.getAddress()) && isBlank(owner.getAddressLine1())) {
61	            missing.add("address");
62	        }
63	        addIfBlank(missing, "city", owner.getCity());
64	        addIfBlank(missing, "telephone", owner.getTelephone());
65	        if (!missing.isEmpty()) {
66	            throw new MissingOwnerFieldsException(missing);
67	        }
68	        return body;
69	    }
70	
71	    private void addIfBlank(List<String> missing, String field, String value) {
72	        if (isBlank(value)) {
73	            missing.add(field);
74	        }
75	    }
76	
77	    private boolean isBlank(String value) {
78	        return value == null || value.isBlank();
79	    }
80	
81	    @Override
82	    public Object handleEmptyBody(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
83	                                  Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
84	        return body;
85	    }
86	
87	    @Override
88	    public HttpInputMessage beforeBodyRead(HttpInputMessage inputMessage, MethodParameter parameter,
89	                                           Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
90	        return inputMessage;
91	    }
92	
93	    @ExceptionHandler(MissingOwnerFieldsException.class)
94	    @ResponseBody
95	    public ResponseEntity<Map<String, Object>> handleMissingOwnerFields(MissingOwnerFieldsException e) {
96	        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(Map.of("errors", e.getFields()));
97	    }
98	
99	    /** Signals that one or more required owner fields were missing or blank. */
