101	
102	        private final List<String> fields;
103	
104	        MissingOwnerFieldsException(List<String> fields) {
105	            this.fields = fields;
106	        }
107	
108	        List<String> getFields() {
109	            return this.fields;
110	        }
111	    }
112	}
