47	/**
48	 * Rejects a create-owner request whose whole identityKey
49	 * ({@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty)}) equals an
50	 * existing owner's, responding 409 Conflict. This single derived key subsumes the former separate
51	 * telephone, email and household duplicate checks: because the telephone is part of the key, two
52	 * members of the same household with different telephones have different keys and are both allowed;
53	 * only an exact full-key match is a duplicate. The householdId is derived deterministically
54	 * from (normalizedLastName, postcode), so owners sharing both are the same household; further
55	 * members of an existing household are admitted (their membershipLevel is capped relative to the
56	 * household). The body is buffered and re-supplied downstream with the householdId filled in.
57	 */
58	@ControllerAdvice
59	@Order(Ordered.HIGHEST_PRECEDENCE)
60	public class OwnerUniqueIdentityAdvice implements RequestBodyAdvice {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final ObjectMapper objectMapper;
67	
68	    public OwnerUniqueIdentityAdvice(ClinicService clinicService, OwnerMapper ownerMapper, ObjectMapper objectMapper) {
69	        this.clinicService = clinicService;
70	        this.ownerMapper = ownerMapper;
71	        this.objectMapper = objectMapper;
72	    }
73	
74	    @Override
75	    public boolean supports(MethodParameter methodParameter, Type targetType,
76	                            Class<? extends HttpMessageConverter<?>> converterType) {
77	        Method method = methodParameter.getMethod();
78	        return OwnerFieldsDto.class.equals(targetType) && method != null
79	            && "addOwner".equals(method.getName());
80	    }
81	
82	    @Override
83	    public HttpInputMessage beforeBodyRead(HttpInputMessage inputMessage, MethodParameter parameter,
84	                                           Type targetType, Class<? extends HttpMessageConverter<?>> converterType)
85	            throws IOException {
86	        byte[] bytes = inputMessage.getBody().readAllBytes();
87	        JsonNode body = objectMapper.readTree(bytes);
88	        String householdId = Households.id(body.path("lastName").asString(""), body.path("postcode").asString(""));
89	        ((ObjectNode) body).put("householdId", householdId);
90	        return buffered(objectMapper.writeValueAsBytes(body), inputMessage.getHeaders());
91	    }
92	
93	    @Override
94	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
95	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
96	        String identityKey = ownerMapper.identityKey(ownerMapper.toOwner((OwnerFieldsDto) body));
97	        for (Owner existing : clinicService.findAllOwners()) {
98	            if (!existing.isDeleted() && identityKey.equals(ownerMapper.identityKey(existing))) {
99	                throw new DuplicateIdentityException();
100	            }
101	        }
102	        return body;
103	    }
104	
105	    @Override
106	    public Object handleEmptyBody(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
107	                                  Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
108	        return body;
109	    }
110	
111	    private HttpInputMessage buffered(byte[] bytes, HttpHeaders headers) {
112	        return new HttpInputMessage() {
113	            @Override
114	            public InputStream getBody() {
115	                return new ByteArrayInputStream(bytes);
116	            }
117	
118	            @Override
119	            public HttpHeaders getHeaders() {
120	                return headers;
121	            }
122	        };
123	    }
124	
125	    @ExceptionHandler(DuplicateIdentityException.class)
126	    @ResponseBody
127	    public ResponseEntity<Void> handleDuplicateIdentity(DuplicateIdentityException e) {
128	        return ResponseEntity.status(HttpStatus.CONFLICT).build();
129	    }
130	
131	    /** Signals that an owner with the same whole identityKey already exists. */
132	    static class DuplicateIdentityException extends RuntimeException {
133	    }
134	}
