33	/**
34	 * Flags every owner response with {@code riskFlag}: true when any risk signal holds — the owner is a
35	 * possible duplicate, the email domain is disposable-adjacent (a subdomain of a known disposable
36	 * domain), or the owner's city is at or over its soft capacity of {@value #SOFT_CAPACITY} owners
37	 * (compared case-insensitively with surrounding whitespace trimmed); otherwise false. Purely
38	 * informational, so it never rejects a request.
39	 */
40	@ControllerAdvice
41	public class OwnerRiskFlagAdvice implements ResponseBodyAdvice<Object> {
42	
43	    private static final int SOFT_CAPACITY = 40;
44	
45	    private static final Set<String> DISPOSABLE_DOMAINS =
46	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
47	
48	    private final ClinicService clinicService;
49	
50	    public OwnerRiskFlagAdvice(ClinicService clinicService) {
51	        this.clinicService = clinicService;
52	    }
53	
54	    @Override
55	    public boolean supports(MethodParameter returnType,
56	                            Class<? extends HttpMessageConverter<?>> converterType) {
57	        return true;
58	    }
59	
60	    @Override
61	    public Object beforeBodyWrite(Object body, MethodParameter returnType, MediaType selectedContentType,
62	                                  Class<? extends HttpMessageConverter<?>> selectedConverterType,
63	                                  ServerHttpRequest request, ServerHttpResponse response) {
64	        if (body instanceof OwnerDto owner) {
65	            owner.setRiskFlag(Boolean.TRUE.equals(owner.getPossibleDuplicate())
66	                || disposableAdjacent(owner.getEmail())
67	                || cityCount(normalize(owner.getCity())) >= SOFT_CAPACITY);
68	        }
69	        return body;
70	    }
71	
72	    private boolean disposableAdjacent(String email) {
73	        if (email == null) {
74	            return false;
75	        }
76	        String domain = normalize(email.substring(email.lastIndexOf('@') + 1));
77	        for (String disposable : DISPOSABLE_DOMAINS) {
78	            if (domain.endsWith("." + disposable)) {
79	                return true;
80	            }
81	        }
82	        return false;
83	    }
84	
85	    private int cityCount(String city) {
86	        if (city.isEmpty()) {
87	            return 0;
88	        }
89	        int count = 0;
90	        for (Owner existing : clinicService.findAllOwners()) {
91	            if (city.equals(normalize(existing.getCity()))) {
92	                count++;
93	            }
94	        }
95	        return count;
96	    }
97	
98	    private String normalize(String value) {
99	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
100	    }
101	}
