38	    private static final AtomicInteger SEQ = new AtomicInteger();
39	
40	    /** Next event for an owner, stamped with a monotonically increasing {@code seq} across creates and
41	     *  the owner segment recomputed from the version-2 identity's region and the membership level. */
42	    public static OwnerCreatedEvent next(Integer ownerId, String primaryIdentifier, Integer membershipLevel) {
43	        String segment = OwnerSegments.of(membershipLevel == null ? 0 : membershipLevel,
44	            MemberIds.regionOf(primaryIdentifier));
45	        return new OwnerCreatedEvent(SEQ.incrementAndGet(), ownerId, primaryIdentifier, membershipLevel, segment);
46	    }
47	
48	    /** Compact JSON rendering with a stable field order, led by the audit {@code schemaVersion}. */
49	    public String toJson() {
50	        return String.format(
51	            "{\"schemaVersion\":%d,\"seq\":%d,\"ownerId\":%s,\"customerCode\":%s,\"membershipLevel\":%s,\"ownerSegment\":%s,\"event\":\"OWNER_CREATED\"}",
52	            SCHEMA_VERSION, seq, ownerId, quote(customerCode), membershipLevel, quote(ownerSegment));
53	    }
54	
55	    private static String quote(String value) {
56	        return value == null ? "null" : "\"" + value + "\"";
57	    }
