32	/**
33	 * Flags every owner response with {@code capacityWarning}: true when the owner's city (compared
34	 * case-insensitively with surrounding whitespace trimmed) already holds between 40 and 49 owners,
35	 * approaching the 50-owner hard limit enforced by {@link OwnerCityCapacityAdvice}; otherwise false.
36	 * Purely informational, so it never rejects a request.
37	 */
38	@ControllerAdvice
39	public class OwnerCapacityWarningAdvice implements ResponseBodyAdvice<Object> {
40	
41	    private static final int WARN_FROM = 40;
42	
43	    private static final int WARN_TO = 49;
44	
45	    private final ClinicService clinicService;
46	
47	    public OwnerCapacityWarningAdvice(ClinicService clinicService) {
48	        this.clinicService = clinicService;
49	    }
50	
51	    @Override
52	    public boolean supports(MethodParameter returnType,
53	                            Class<? extends HttpMessageConverter<?>> converterType) {
54	        return true;
55	    }
56	
57	    @Override
58	    public Object beforeBodyWrite(Object body, MethodParameter returnType, MediaType selectedContentType,
59	                                  Class<? extends HttpMessageConverter<?>> selectedConverterType,
60	                                  ServerHttpRequest request, ServerHttpResponse response) {
61	        if (body instanceof OwnerDto owner) {
62	            int count = cityCount(normalize(owner.getCity()));
63	            owner.setCapacityWarning(count >= WARN_FROM && count <= WARN_TO);
64	        }
65	        return body;
66	    }
67	
68	    private int cityCount(String city) {
69	        if (city.isEmpty()) {
70	            return 0;
71	        }
72	        int count = 0;
73	        for (Owner existing : clinicService.findAllOwners()) {
74	            if (city.equals(normalize(existing.getCity()))) {
75	                count++;
76	            }
77	        }
78	        return count;
79	    }
80	
81	    private String normalize(String value) {
82	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
83	    }
84	}
