52	    @Override
53	    public boolean supports(MethodParameter methodParameter, Type targetType,
54	                            Class<? extends HttpMessageConverter<?>> converterType) {
55	        Method method = methodParameter.getMethod();
56	        return OwnerFieldsDto.class.equals(targetType) && method != null
57	            && "addOwner".equals(method.getName());
58	    }
59	
60	    @Override
61	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
62	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
63	        OwnerFieldsDto owner = (OwnerFieldsDto) body;
64	        if (isOutOfRange(owner.getPostcode(), owner.getCity())) {
65	            throw new InvalidPostcodeException();
66	        }
67	        return body;
