16	package org.springframework.samples.petclinic.util;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	import java.time.LocalDate;
22	import java.util.Collection;
23	import java.util.HashSet;
24	import java.util.Set;
25	
26	import org.springframework.samples.petclinic.model.Owner;
27	
28	/**
29	 * Builds and reads the unified {@code <REGION><FY><HASH8><CHK>} owner member id: REGION is the
30	 * region resolved from the postcode, FY is the 2-digit fiscal year of the registration date, HASH8
31	 * is the first 8 upper-case hex characters of SHA-256 over (normalizedTelephone + lastName), and CHK
32	 * is a single Luhn check digit over the digits of {@code <REGION><FY><HASH8>}.
33	 */
34	public final class MemberIds {
35	
36	    private MemberIds() {
37	    }
38	
39	    /**
40	     * Build the {@code <REGION><FY><HASH8><CHK>} member id under the version-2 algorithm: the visible
41	     * REGION prefix stays the plain region (so 'locality' reads back plain), while HASH8 mixes the fixed
42	     * 'V2' version tag and the region into the hashed material so the id differs from every version-1 id.
43	     */
44	    public static String build(String city, String postcode, String telephone, String lastName, LocalDate registrationDate) {
45	        String region = Localities.regionFor(city, postcode);
46	        String body = region
47	            + String.format("%02d", FiscalYears.startYear(registrationDate) % 100)
48	            + hash8("V2" + region + telephone + lastName);
49	        return body + CheckDigits.luhn(body);
50	    }
51	
52	    /**
53	     * Build the member id, then de-duplicate it against {@code existingOwners} by appending
54	     * {@code -<n>} with the smallest {@code n >= 2} that makes it unique.
55	     */
56	    public static String buildUnique(String city, String postcode, String telephone, String lastName,
57	            LocalDate registrationDate, Collection<Owner> existingOwners) {
58	        String base = build(city, postcode, telephone, lastName, registrationDate);
59	        Set<String> taken = new HashSet<>();
60	        for (Owner owner : existingOwners) {
61	            taken.add(owner.getMemberId());
62	        }
63	        String candidate = base;
64	        for (int n = 2; taken.contains(candidate); n++) {
65	            candidate = base + "-" + n;
66	        }
67	        return candidate;
68	    }
69	
70	    /** The region portion of a member id (its leading run of letters), or null when absent. */
71	    public static String regionOf(String memberId) {
72	        if (memberId == null) {
73	            return null;
74	        }
75	        int end = 0;
76	        while (end < memberId.length() && Character.isLetter(memberId.charAt(end))) {
77	            end++;
78	        }
79	        return memberId.substring(0, end);
80	    }
81	
82	    /** The {@code FY<YY>} label carried by the member id (its 2 fiscal-year digits after the region), or null when absent. */
83	    public static String fiscalYearLabel(String memberId) {
84	        String region = regionOf(memberId);
85	        return region == null ? null : "FY" + memberId.substring(region.length(), region.length() + 2);
86	    }
87	
88	    private static String hash8(String value) {
89	        try {
90	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
91	            return String.format("%02X%02X%02X%02X", digest[0], digest[1], digest[2], digest[3]);
92	        }
93	        catch (NoSuchAlgorithmException ex) {
94	            throw new IllegalStateException(ex);
95	        }
96	    }
97	}
