17	
18	import java.util.Collection;
19	
20	import org.springframework.samples.petclinic.model.Owner;
21	
22	/** Soft-match detection for a new owner against the existing owners. */
23	public final class PossibleDuplicates {
24	
25	    private PossibleDuplicates() {
26	    }
27	
28	    /**
29	     * Id of an existing (non-deleted) owner this one is a suspected (soft) duplicate of, or {@code null}.
30	     *
31	     * <p>A soft match is an owner whose {@link IdentityKeys#of identityKey} differs (so it is not a hard
32	     * 409 duplicate) yet whose {@code soundex(lastName)} and postcode both match: the same household
33	     * reached under a different telephone or email.
34	     */
35	    public static Integer matchIn(Owner owner, Collection<Owner> existing) {
36	        String key = IdentityKeys.of(owner);
37	        String soundex = IdentityKeys.soundex(owner.getLastName());
38	        String postcode = owner.getPostcode();
39	        for (Owner other : existing) {
40	            if (!other.isDeleted() && postcode != null && postcode.equals(other.getPostcode())
41	                && soundex.equals(IdentityKeys.soundex(other.getLastName()))
42	                && !key.equals(IdentityKeys.of(other))) {
43	                return other.getId();
44	            }
45	        }
46	        return null;
47	    }
48	}
