16	package org.springframework.samples.petclinic.util;
17	
18	import java.time.LocalDate;
19	import java.util.Collection;
20	
21	import org.springframework.samples.petclinic.model.Owner;
22	
23	/**
24	 * Membership points/level scoring and the household level ceiling. Kept as small pure functions so
25	 * both the owner mapper (for display) and the create path (to freeze a capped level) share one source.
26	 */
27	public final class MembershipLevels {
28	
29	    private MembershipLevels() {
30	    }
31	
32	    /** Membership points: +2 for an email, +1 when namesakeCount is 0, +2 for a household of 3 or more, +3 for tenure over 365 days. */
33	    public static int points(Owner owner) {
34	        int points = 0;
35	        if (owner.getEmail() != null) {
36	            points += 2;
37	        }
38	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
39	            points += 1;
40	        }
41	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
42	            points += 2;
43	        }
44	        if (tenureFiscalYears(owner) >= 1) {
45	            points += 3;
46	        }
47	        return points;
48	    }
49	
50	    /** Numeric level derived from membershipPoints: 1 (0-1), 2 (2-3), 3 (4-5), 4 (6 or more). */
51	    public static int level(Owner owner) {
52	        int points = points(owner);
53	        if (points <= 1) {
54	            return 1;
55	        }
56	        if (points <= 3) {
57	            return 2;
58	        }
59	        return points <= 5 ? 3 : 4;
60	    }
61	
62	    /**
63	     * The level a new owner may be given: at most one above the maximum level among the existing
64	     * (non-deleted) members of their household. With no existing household member no cap applies and
65	     * the owner's own level is returned.
66	     */
67	    public static Integer cap(Owner owner, Collection<Owner> existing) {
68	        String householdId = owner.getHouseholdId();
69	        int maxOther = Integer.MIN_VALUE;
70	        for (Owner other : existing) {
71	            if (householdId != null && householdId.equals(other.getHouseholdId()) && !other.isDeleted()) {
72	                maxOther = Math.max(maxOther, level(other));
73	            }
74	        }
75	        int own = level(owner);
76	        return maxOther == Integer.MIN_VALUE ? own : Math.min(own, maxOther + 1);
77	    }
78	
79	    private static int tenureFiscalYears(Owner owner) {
80	        LocalDate registrationDate = owner.getRegistrationDate();
81	        if (registrationDate == null) {
82	            return 0;
83	        }
84	        return FiscalYears.elapsed(registrationDate, LocalDate.now());
85	    }
86	}
