17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	import java.util.Collection;
22	import java.util.Locale;
23	
24	import org.springframework.samples.petclinic.model.Owner;
25	
26	/**
27	 * Deterministic household identity: the id is the first 12 hex characters of SHA-256 over
28	 * {@code normalizedLastName + '|' + postcode}, so owners with the same last name and postcode
29	 * share a household automatically.
30	 */
31	public final class Households {
32	
33	    private Households() {
34	    }
35	
36	    /** The deterministic version-2 householdId for the given last name and postcode: the SHA-256 hash
37	     *  mixes in the fixed 'V2' version tag so no id produced under version 1 recurs. */
38	    public static String id(String lastName, String postcode) {
39	        String key = "V2" + normalize(lastName) + '|' + (postcode == null ? "" : postcode);
40	        byte[] digest = sha256(key);
41	        StringBuilder hex = new StringBuilder(12);
42	        for (int i = 0; i < 6; i++) {
43	            hex.append(String.format("%02x", digest[i]));
44	        }
45	        return hex.toString();
46	    }
47	
48	    /** Whether any existing owner already belongs to the household identified by {@code householdId}. */
49	    public static boolean isDuplicate(Collection<Owner> existing, String householdId) {
50	        for (Owner other : existing) {
51	            if (householdId.equals(other.getHouseholdId())) {
52	                return true;
53	            }
54	        }
55	        return false;
56	    }
57	
58	    private static String normalize(String value) {
59	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
60	    }
61	
62	    private static byte[] sha256(String value) {
63	        try {
64	            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
65	        }
66	        catch (NoSuchAlgorithmException ex) {
67	            throw new IllegalStateException(ex);
68	        }
69	    }
70	}
