17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	import java.util.Locale;
22	
23	import org.springframework.samples.petclinic.model.Owner;
24	
25	/**
26	 * The owner identity key: the SHA-256 hex of
27	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. Duplicate detection
28	 * compares this key; the soft-match compares {@link #soundex(String)} of the last name.
29	 */
30	public final class IdentityKeys {
31	
32	    private IdentityKeys() {
33	    }
34	
35	    /** The version-2 identity key of the given owner: the SHA-256 input mixes in the fixed 'V2' version
36	     *  tag so no key produced under version 1 recurs. */
37	    public static String of(Owner owner) {
38	        String raw = "V2" + orEmpty(owner.getTelephone()) + '|' + orEmpty(owner.getEmail()) + '|' + soundex(owner.getLastName());
39	        return sha256Hex(raw);
40	    }
41	
42	    /** The American Soundex code of {@code name} (letter + 3 digits), or empty when there is no letter. */
43	    public static String soundex(String name) {
44	        String letters = (name == null ? "" : name.toUpperCase(Locale.ROOT)).replaceAll("[^A-Z]", "");
45	        if (letters.isEmpty()) {
46	            return "";
47	        }
48	        StringBuilder out = new StringBuilder().append(letters.charAt(0));
49	        char prev = code(letters.charAt(0));
50	        for (int i = 1; i < letters.length() && out.length() < 4; i++) {
51	            char c = letters.charAt(i);
52	            char digit = code(c);
53	            if (digit != '0' && digit != prev) {
54	                out.append(digit);
55	            }
56	            if (c != 'H' && c != 'W') {
57	                prev = digit;
58	            }
59	        }
60	        while (out.length() < 4) {
61	            out.append('0');
62	        }
63	        return out.toString();
64	    }
65	
66	    private static char code(char c) {
67	        return switch (c) {
68	            case 'B', 'F', 'P', 'V' -> '1';
69	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
70	            case 'D', 'T' -> '3';
71	            case 'L' -> '4';
72	            case 'M', 'N' -> '5';
73	            case 'R' -> '6';
74	            default -> '0';
75	        };
76	    }
77	
78	    private static String orEmpty(String value) {
79	        return value == null ? "" : value;
80	    }
81	
82	    private static String sha256Hex(String value) {
83	        try {
84	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
85	            StringBuilder hex = new StringBuilder(digest.length * 2);
86	            for (byte b : digest) {
87	                hex.append(String.format("%02x", b));
88	            }
89	            return hex.toString();
90	        }
91	        catch (NoSuchAlgorithmException ex) {
92	            throw new IllegalStateException(ex);
93	        }
94	    }
95	}
