18	import java.time.DayOfWeek;
19	import java.time.LocalDate;
20	import java.util.Set;
21	
22	/**
23	 * Rolls dates forward off the weekend and public holidays onto a business day.
24	 */
25	public final class BusinessDays {
26	
27	    /** Fixed public holidays skipped by the business-day roll. */
28	    private static final Set<LocalDate> HOLIDAYS = Set.of(
29	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
30	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
31	        LocalDate.parse("2026-12-28"));
32	
33	    private BusinessDays() {
34	    }
35	
36	    private static boolean isBusinessDay(LocalDate date) {
37	        DayOfWeek day = date.getDayOfWeek();
38	        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !HOLIDAYS.contains(date);
39	    }
40	
41	    /** Return {@code date} unchanged when it is a business day, else the next non-weekend, non-holiday day. */
42	    public static LocalDate toBusinessDay(LocalDate date) {
43	        while (!isBusinessDay(date)) {
44	            date = date.plusDays(1);
45	        }
46	        return date;
47	    }
48	}
